dtsPropsFor.PlayButton:
/** The song this button plays / pauses. */
song: { id: number; slug: string; title: { be: string; en: string }; audio: string; cover: string; coverFull: string; date: string; model: string; lyricsAuthor: { be: string; en: string }; description: { be: string; en: string }; lyrics: { be: string; en: string }; lyricsNotes: { be: string; en: string }; visualizer?: string; stylePrompt: string; lyricsPrompt: string };
/** Larger dock-sized variant (used on the song card). */
large?: boolean;

dtsPropsFor.SongScreen:
/** The song rendered on this full-screen card. */
song: { id: number; slug: string; title: { be: string; en: string }; audio: string; cover: string; coverFull: string; date: string; model: string; lyricsAuthor: { be: string; en: string }; description: { be: string; en: string }; lyrics: { be: string; en: string }; lyricsNotes: { be: string; en: string }; visualizer?: string; stylePrompt: string; lyricsPrompt: string };
/** Total number of songs (shown as "№ NN / total"). */
total: number;
/** Gallery rhythm: every 2nd rendered song sits on --paper-2. */
alt?: boolean;
/** Last song on the page: the "next" chevron leads to the outro, not a song. */
isLast?: boolean;

dtsPropsFor.ProgressNav:
/** The songs, in page order, rendered as a vertical tick rail. */
songs: Array<{ id: number; slug: string; title: { be: string; en: string }; audio: string; cover: string; coverFull: string; date: string; model: string; lyricsAuthor: { be: string; en: string }; description: { be: string; en: string }; lyrics: { be: string; en: string }; lyricsNotes: { be: string; en: string }; visualizer?: string; stylePrompt: string; lyricsPrompt: string }>;
/** Active section index (0 = intro, 1..N = songs); highlights the matching tick. */
activeIndex: number;

dtsPropsFor.TopBar:
/** Track number of the song currently in view, or null on the intro/outro. */
activeSong: number | null;
/** Total number of songs. */
total: number;
/** All songs, for the quick-nav dropdown. */
songs: Array<{ id: number; slug: string; title: { be: string; en: string }; audio: string; cover: string; coverFull: string; date: string; model: string; lyricsAuthor: { be: string; en: string }; description: { be: string; en: string }; lyrics: { be: string; en: string }; lyricsNotes: { be: string; en: string }; visualizer?: string; stylePrompt: string; lyricsPrompt: string }>;
/** Which bookend screen is active, when not on a song. */
edge: 'intro' | 'outro' | null;

dtsPropsFor.CoverViz:
/** The song whose visualizer to mount (dispatches on song.visualizer, default embers). */
song: { id: number; slug: string; title: { be: string; en: string }; audio: string; cover: string; coverFull: string; date: string; model: string; lyricsAuthor: { be: string; en: string }; description: { be: string; en: string }; lyrics: { be: string; en: string }; lyricsNotes: { be: string; en: string }; visualizer?: string; stylePrompt: string; lyricsPrompt: string };
/** True while the song is actually sounding (not paused). */
playing: boolean;

dtsPropsFor.PromptDisclosure:
/** Summary label shown on the collapsed disclosure. */
label: string;
/** The revealed body text (lyrics, notes, or a generation prompt). */
content: string;
/** Optional caption shown above the content (e.g. a translation disclaimer). */
note?: string;
/** Optional second block under the main content, with its own caption (e.g. the Belarusian original beneath an English translation). */
original?: { label: string; content: string };
/** Render the content as Markdown prose instead of preformatted text. */
markdown?: boolean;
/** Show copy-to-clipboard buttons on the text blocks. */
copyable?: boolean;

dtsPropsFor.Outro:
/** Total number of songs (for the "NN tracks" line). */
total: number;
/** Current page order of the track list. */
order: 'chrono' | 'newest';
/** Toggles between chronological and newest-first order. */
onToggleOrder: () => void;
